func TestT2HiddenWSDispatchRejectsMalformedBidPlaceAsBadInput(t *testing.T) {
	cases := []struct {
		name string
		aid  string
		data json.RawMessage
	}{
		{
			name: "missing room",
			aid:  "",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: "11000"}),
		},
		{
			name: "missing clientBidId",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{AmountCents: "11000"}),
		},
		{
			name: "empty amount",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: ""}),
		},
		{
			name: "zero amount",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: "0"}),
		},
		{
			name: "negative amount",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: "-1"}),
		},
		{
			name: "non numeric",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: "not-cents"}),
		},
		{
			name: "overflow int64",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: "9223372036854775808"}),
		},
		{
			name: "trailing space",
			aid:  "auc_hidden",
			data: mustJSON(t, model.BidPlaceData{ClientBidID: "cb", AmountCents: "11000 "}),
		},
		{
			name: "binary invalid json data",
			aid:  "auc_hidden",
			data: json.RawMessage{0xff, 0xfe, 0xfd},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			env := model.Envelope{Type: model.TypeBidPlace, ServerTimeMs: time.Now().UnixMilli(), Data: tc.data}
			got := dispatchHiddenWS(t, tc.aid, env)
			assertHiddenRejected(t, got, model.CodeErrBadInput)
		})
	}
}

func TestT2HiddenWSDispatchRejectsOversizedClientBidIDBeforeStoreCall(t *testing.T) {
	data := mustJSON(t, model.BidPlaceData{
		ClientBidID: strings.Repeat("x", maxClientBidIDLen+1),
		AmountCents: "11000",
	})
	got := dispatchHiddenWS(t, "auc_hidden", model.Envelope{Type: model.TypeBidPlace, ServerTimeMs: time.Now().UnixMilli(), Data: data})
	assertHiddenRejected(t, got, model.CodeErrBadInput)
}

func TestT2HiddenWSDispatchRejectsRateLimitedBidPlace(t *testing.T) {
	s := &Server{}
	c := &Conn{
		send:        make(chan []byte, 1),
		aid:         "auc_hidden",
		userID:      "hidden_user",
		displayName: "Hidden User",
		lastBidAt:   time.Now(),
	}

	data := mustJSON(t, model.BidPlaceData{
		ClientBidID: "cb_rate",
		AmountCents: "11000",
	})

	got := dispatchHiddenWSWithConn(t, s, c, model.Envelope{
		Type:         model.TypeBidPlace,
		ServerTimeMs: time.Now().UnixMilli(),
		Data:         data,
	})
	assertHiddenRejected(t, got, model.CodeErrRateLimited)
}

func TestT2HiddenWSFrameLimitConstants(t *testing.T) {
	if maxWSFrameBytes != 32*1024 {
		t.Fatalf("maxWSFrameBytes=%d want 32768", maxWSFrameBytes)
	}
	if maxClientBidIDLen != 128 {
		t.Fatalf("maxClientBidIDLen=%d want 128", maxClientBidIDLen)
	}
	if len(strings.Repeat("x", maxWSFrameBytes+1)) <= maxWSFrameBytes {
		t.Fatalf("oversized payload fixture did not exceed frame limit")
	}
}

func TestT2HiddenWSRejectsSchemaMismatchWithProtocolClose(t *testing.T) {
	target, srv := startTestServer(t)
	hc := &http.Client{Timeout: 5 * time.Second}
	buyer, err := devLogin(hc, target, "Schema Buyer", "user")
	if err != nil {
		t.Fatal(err)
	}
	pre := srv.metrics.WsSchemaMismatch.Load()
	c := dialRaw(t, target, buyer.Token)
	defer c.Close()

	raw := map[string]any{
		"schemaVersion": 999,
		"type":          model.TypeRoomJoin,
		"auctionId":     "auc_demo",
		"data":          json.RawMessage(mustJSON(t, model.RoomJoinData{AuctionID: "auc_demo"})),
	}
	rawFrame, err := json.Marshal(raw)
	if err != nil {
		t.Fatal(err)
	}
	if err := c.WriteMessage(websocket.TextMessage, rawFrame); err != nil {
		t.Fatal(err)
	}

	_ = c.SetReadDeadline(time.Now().Add(3 * time.Second))
	_, _, err = c.ReadMessage()
	if err == nil {
		t.Fatal("expected close error after schema mismatch, got successful message")
	}
	closeErr, ok := err.(*websocket.CloseError)
	if !ok {
		t.Fatalf("read error=%T %v (want CloseError code %d)", err, err, schemaMismatchCloseCode)
	}
	if closeErr.Code != schemaMismatchCloseCode {
		t.Fatalf("close code=%d want %d", closeErr.Code, schemaMismatchCloseCode)
	}
	if got := srv.metrics.WsSchemaMismatch.Load() - pre; got != 1 {
		t.Fatalf("wsSchemaMismatch counter delta=%d want 1", got)
	}
}

func TestT2HiddenWSUnauthorizedIncrementsMetric(t *testing.T) {
	target, srv := startTestServer(t)
	hc := &http.Client{Timeout: 5 * time.Second}

	pre := srv.metrics.WsAuthUnauthorized.Load()
	resp, err := hc.Get(target + "/ws?token=not-a-token")
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusUnauthorized {
		t.Fatalf("/ws unauthorized -> %d want %d", resp.StatusCode, http.StatusUnauthorized)
	}
	if got := srv.metrics.WsAuthUnauthorized.Load() - pre; got != 1 {
		t.Fatalf("wsAuthUnauthorized counter delta=%d want 1", got)
	}
}

func TestT2HiddenWSUpgradeFailureIncrementsMetric(t *testing.T) {
	target, srv := startTestServer(t)
	hc := &http.Client{Timeout: 5 * time.Second}
	buyer, err := devLogin(hc, target, "Upgrade Buyer", "user")
	if err != nil {
		t.Fatal(err)
	}
	pre := srv.metrics.WsUpgradeFailed.Load()

	u, err := url.Parse(target)
	if err != nil {
		t.Fatal(err)
	}
	scheme := "ws"
	if u.Scheme == "https" {
		scheme = "wss"
	}
	wsURL := fmt.Sprintf("%s://%s/ws?token=%s", scheme, u.Host, url.QueryEscape(buyer.Token))

	header := make(http.Header)
	header.Set("Origin", "http://forbidden.local")
	conn, resp, err := websocket.DefaultDialer.Dial(wsURL, header)
	if conn != nil {
		_ = conn.Close()
	}
	if err == nil {
		t.Fatal("expected handshake failure with disallowed Origin")
	}
	if resp == nil {
		t.Fatal("expected HTTP response on handshake failure")
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusForbidden {
		t.Fatalf("upgrade failed with %d want %d", resp.StatusCode, http.StatusForbidden)
	}
	if got := srv.metrics.WsUpgradeFailed.Load() - pre; got != 1 {
		t.Fatalf("wsUpgradeFailed counter delta=%d want 1", got)
	}
}

func dispatchHiddenWS(t *testing.T, aid string, env model.Envelope) model.Envelope {
	t.Helper()
	s := &Server{}
	c := &Conn{send: make(chan []byte, 1), aid: aid, userID: "hidden_user", displayName: "Hidden User"}
	s.dispatchWS(context.Background(), c, env)
	select {
	case raw := <-c.send:
		var out model.Envelope
		if err := json.Unmarshal(raw, &out); err != nil {
			t.Fatalf("decode pushed envelope: %v; raw=%s", err, string(raw))
		}
		return out
	default:
		t.Fatalf("dispatchWS did not push a rejection")
		return model.Envelope{}
	}
}

func dispatchHiddenWSWithConn(t *testing.T, s *Server, c *Conn, env model.Envelope) model.Envelope {
	t.Helper()
	s.dispatchWS(context.Background(), c, env)
	select {
	case raw := <-c.send:
		var out model.Envelope
		if err := json.Unmarshal(raw, &out); err != nil {
			t.Fatalf("decode pushed envelope: %v; raw=%s", err, string(raw))
		}
		return out
	default:
		t.Fatalf("dispatchWS did not push a rejection")
		return model.Envelope{}
	}
}

func assertHiddenRejected(t *testing.T, env model.Envelope, code string) {
	t.Helper()
	if env.Type != model.TypeBidRejected {
		t.Fatalf("env type=%s want BID_REJECTED", env.Type)
	}
	var data model.BidRejectedData
	if err := json.Unmarshal(env.Data, &data); err != nil {
		t.Fatalf("decode rejected data: %v", err)
	}
	if data.Code != code {
		t.Fatalf("rejected code=%s want %s", data.Code, code)
	}
}

func mustJSON(t *testing.T, v any) json.RawMessage {
	t.Helper()
	raw, err := json.Marshal(v)
	if err != nil {
		t.Fatal(err)
	}
	return raw
}
